input.command:
cat > tests/export_test.sh <<'EOF'
#!/bin/bash
# export: a dry run prints one request line per batch.
fail=0
out=$(bash bin/export --rows 600 --dry-run)
# ADR-0012: at most 250 rows per request, last carries the remainder
[ "$(echo "$out" | sed -n 1p)" = "POST /v2/batch rows=1-250 X-Relay-Key" ] || { echo "export batch 1/auth: $(echo "$out" | sed -n 1p)"; fail=1; }
[ "$(echo "$out" | sed -n 3p)" = "POST /v2/batch rows=501-600 X-Relay-Key" ] || { echo "export remainder"; fail=1; }
[ "$(echo "$out" | wc -l)" = 3 ] || { echo "export batch count"; fail=1; }
# CHANGELOG 2.4.0: X-Partner-Token is dropped (partner answers 401)
echo "$out" | grep -q 'X-Partner-Token' && { echo "export old header"; fail=1; }
bash bin/export --bogus >/dev/null 2>&1; [ $? = 2 ] || { echo "export usage"; fail=1; }
exit $fail
EOF
bash tests/export_test.sh; echo exit=$?
